import os
from azure.ai.formrecognizer import DocumentAnalysisClient
from azure.core.credentials import AzureKeyCredential

def extract_layout_from_document(document_path: str) -> dict:
    """
    Extracts layout elements (paragraphs, tables, lines, etc.) from a document using Azure Form Recognizer.

    Args:
        document_path: Path to the document file (PDF, image, etc.)

    Returns:
        Dictionary containing extracted layout elements with their types, content, and bounding boxes.
    """
    endpoint = os.getenv("AZURE_FORM_RECOGNIZER_ENDPOINT")
    key = os.getenv("AZURE_FORM_RECOGNIZER_KEY")
    model_id = "prebuilt-layout"

    if not endpoint or not key:
        raise ValueError("Azure Form Recognizer endpoint and key must be set in environment variables")

    document_analysis_client = DocumentAnalysisClient(
        endpoint=endpoint, credential=AzureKeyCredential(key)
    )

    with open(document_path, "rb") as f:
        poller = document_analysis_client.begin_analyze_document(
            model_id=model_id, document=f
        )

    result = poller.result()

    layout_elements = {
        "paragraphs": [],
        "tables": [],
        "lines": [],
        "selection_marks": []
    }

    for paragraph in result.paragraphs:
        layout_elements["paragraphs"].append({
            "content": paragraph.content,
            "bounding_box": [{"x": point.x, "y": point.y} for point in paragraph.polygon],
            "role": paragraph.role
        })

    for table in result.tables:
        table_data = {
            "row_count": table.row_count,
            "column_count": table.column_count,
            "cells": [],
            "bounding_box": [{"x": point.x, "y": point.y} for point in table.bounding_regions[0].polygon]
        }
        for cell in table.cells:
            table_data["cells"].append({
                "content": cell.content,
                "row_index": cell.row_index,
                "column_index": cell.column_index,
                "bounding_box": [{"x": point.x, "y": point.y} for point in cell.bounding_regions[0].polygon]
            })
        layout_elements["tables"].append(table_data)

    for line in result.pages[0].lines:
        layout_elements["lines"].append({
            "content": line.content,
            "bounding_box": [{"x": point.x, "y": point.y} for point in line.polygon]
        })

    for selection_mark in result.pages[0].selection_marks:
        layout_elements["selection_marks"].append({
            "state": selection_mark.state,
            "bounding_box": [{"x": point.x, "y": point.y} for point in selection_mark.polygon]
        })

    return layout_elements
